# Kaggle kernel script, generated by kaggle/kaggle_job.py. Do not edit by hand.
# Everything this run needs is embedded below (JOB); nothing else is uploaded.
import json
import os
import shutil
import signal
import subprocess
import sys
import time

JOB = json.loads(r'''__JOB_JSON__''')

WORK = os.environ.get("MDMS_KAGGLE_WORKING", "/kaggle/working")
TEMP = os.environ.get("MDMS_KAGGLE_TEMP", "/kaggle/temp")
OUT = os.path.join(WORK, "out")
LOGS = os.path.join(OUT, "logs")
REPO = os.path.join(TEMP, "repo")


def sh(cmd, timeout, cwd=None, log_name=None):
    """Run cmd in its own process group; kill the whole group on timeout."""
    t0 = time.time()
    log_path = os.path.join(LOGS, log_name) if log_name else None
    logf = open(log_path, "w") if log_path else subprocess.DEVNULL
    try:
        p = subprocess.Popen(cmd, cwd=cwd, stdout=logf, stderr=subprocess.STDOUT,
                             start_new_session=True, shell=isinstance(cmd, str))
        try:
            rc = p.wait(timeout=timeout)
            timed_out = False
        except subprocess.TimeoutExpired:
            os.killpg(p.pid, signal.SIGKILL)
            p.wait()
            rc, timed_out = -9, True
    except FileNotFoundError as exc:
        if log_path:
            logf.write(f"not found: {exc}\n")
        rc, timed_out = 127, False
    finally:
        if log_path:
            logf.close()
    return dict(cmd=cmd if isinstance(cmd, str) else " ".join(cmd), rc=rc, timed_out=timed_out,
                seconds=round(time.time() - t0, 3), log=log_name)


def capture(cmd):
    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=60).stdout.strip()
    except Exception as exc:  # recorded in the summary, not hidden
        return f"unavailable: {exc!r}"


def main():
    os.makedirs(LOGS, exist_ok=True)
    os.makedirs(TEMP, exist_ok=True)
    t_start = time.time()
    summary = dict(job_id=JOB["job_id"], job=JOB["job"], requested_sha=JOB["sha"],
                   branch=JOB["branch"], started_unix=t_start, steps=[], ok=False)
    summary["gpus"] = capture(["nvidia-smi", "--query-gpu=name,memory.total,driver_version",
                               "--format=csv,noheader"]).splitlines()
    summary["nvcc_version"] = capture(["nvcc", "--version"]).splitlines()[-1:] or []
    summary["python"] = sys.version.split()[0]

    def finish(ok):
        summary["ok"] = bool(ok)
        summary["seconds"] = round(time.time() - t_start, 3)
        with open(os.path.join(OUT, "job_summary.json"), "w") as f:
            json.dump(summary, f, indent=2)
        print(json.dumps(summary, indent=2))

    if os.path.exists(REPO):
        shutil.rmtree(REPO)
    step = sh(["git", "clone", "--quiet", "--branch", JOB["branch"], JOB["repo_url"], REPO],
              300, log_name="00_clone.log")
    summary["steps"].append(step)
    if step["rc"] != 0:
        return finish(False)
    step = sh(["git", "checkout", "--quiet", JOB["sha"]], 60, cwd=REPO, log_name="01_checkout.log")
    summary["steps"].append(step)
    head = capture(["git", "-C", REPO, "rev-parse", "HEAD"])
    summary["checked_out_sha"] = head
    if step["rc"] != 0 or head != JOB["sha"]:
        summary["error"] = "checked-out commit differs from the requested commit"
        return finish(False)

    ok = True
    for idx, c in enumerate(JOB["commands"]):
        step = sh(c["cmd"], c.get("timeout_sec", JOB["default_timeout_sec"]), cwd=REPO,
                  log_name=f"{idx + 2:02d}_{c['name']}.log")
        step["name"] = c["name"]
        summary["steps"].append(step)
        if step["rc"] != 0:
            ok = False
            if JOB.get("stop_on_failure", True):
                break
    # collect outputs (small files only)
    copied = []
    for rel in JOB.get("collect", []):
        src = os.path.join(REPO, rel)
        if os.path.isdir(src):
            dst = os.path.join(OUT, rel)
            shutil.copytree(src, dst, dirs_exist_ok=True)
            copied.append(rel + "/")
        elif os.path.exists(src):
            os.makedirs(os.path.dirname(os.path.join(OUT, rel)) or OUT, exist_ok=True)
            shutil.copy2(src, os.path.join(OUT, rel))
            copied.append(rel)
    summary["collected"] = copied
    return finish(ok)


if __name__ == "__main__":
    main()
